/* ---------- drawing helpers for this lesson (prefixed MW_ so they never clash with engine globals) ---------- */
const MW_A=P('a');                                    /* the wave a, said as the letter */
const MW_G='#5C6577', MW_LG='#ADB5BD';
const MW_F='font-family="Nunito Sans, sans-serif"';
const MW_T=(x,y,t,o={})=>`<text x="${x}" y="${y}" ${MW_F} font-size="${o.fs||24}" font-weight="${o.fw||600}" text-anchor="${o.a||'start'}" fill="${o.fill||'#18213A'}"${o.op?` fill-opacity="${o.op}"`:''}>${t}</text>`;
const MW_L=(x1,y1,x2,y2,col=MW_G,w=2,ex='')=>`<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${col}" stroke-width="${w}" stroke-linecap="round" ${ex}/>`;
const MW_box=(x,y,w,h,o={})=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${o.r??14}" fill="${o.fill||'#FFFFFF'}" stroke="${o.st||'#CED4DA'}" stroke-width="${o.sw||2}"${o.dash?` stroke-dasharray="${o.dash}"`:''}/>`;
const MW_ar=(x1,y1,x2,y2,col='#18213A',w=4,dash='')=>{const a=Math.atan2(y2-y1,x2-x1),h=16;return MW_L(x1,y1,x2-h*.6*Math.cos(a),y2-h*.6*Math.sin(a),col,w,dash?`stroke-dasharray="${dash}"`:'')+`<polygon points="${x2},${y2} ${(x2-h*Math.cos(a)+h*.5*Math.sin(a)).toFixed(1)},${(y2-h*Math.sin(a)-h*.5*Math.cos(a)).toFixed(1)} ${(x2-h*Math.cos(a)-h*.5*Math.sin(a)).toFixed(1)},${(y2-h*Math.sin(a)+h*.5*Math.cos(a)).toFixed(1)}" fill="${col}"/>`};
const MW_sub=(a,b)=>`${a}<tspan baseline-shift="sub" font-size="70%">${b}</tspan>`;
const MW_badge=(x,y,n,col=INK,op=1,r=17)=>{col=col||INK;op=op??1;return `<circle cx="${x}" cy="${y}" r="${r}" fill="${col}" fill-opacity="${op}"/>`+MW_T(x,y+8,n,{fs:22,fw:800,a:'middle',fill:'#FFFFFF'})};
const MW_curve=(f,t0,t1,x0,x1,yc,k,col,w=4,n=90)=>{let p=[];for(let i=0;i<=n;i++){const t=t0+(t1-t0)*i/n;p.push(`${(x0+(x1-x0)*i/n).toFixed(1)},${(yc-k*f(t)).toFixed(1)}`)}return `<polyline points="${p.join(' ')}" fill="none" stroke="${col}" stroke-width="${w}" stroke-linejoin="round" stroke-linecap="round"/>`};
const MW_X=(x,y,s,col)=>MW_L(x-s,y-s,x+s,y+s,col,8)+MW_L(x-s,y+s,x+s,y-s,col,8);
/* a waveguide arm drawn as a hollow channel */
const MW_guide=(x,y,w,h,col)=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" fill="#FFFFFF" stroke="${col}" stroke-width="3"/>`;
/* a tee: through guide x0..x1 at y (height h), branch of width bw going up (dir -1) or down (dir 1) by len from the middle */
const MW_tee=(x0,x1,y,h,bw,len,dir,col,bcol)=>{const xm=(x0+x1)/2,by=dir<0?y-len:y+h;return MW_guide(x0,y,x1-x0,h,col)+MW_guide(xm-bw/2,by,bw,len,bcol)+`<rect x="${xm-bw/2+2}" y="${dir<0?y-2:y+h-4}" width="${bw-4}" height="6" fill="#FFFFFF"/>`};
/* the TE10 cross-section: a × b with E lines across b, strongest in the middle; wall = 'broad' or 'narrow' highlighted */
const MW_te10=(x,y,w,h,wall,col)=>{let s=`<rect x="${x}" y="${y}" width="${w}" height="${h}" fill="#FFFFFF" stroke="${MW_G}" stroke-width="2"/>`;
 if(wall==='broad')s+=MW_L(x,y,x+w,y,col,6);else s+=MW_L(x,y,x,y+h,col,6)+MW_L(x+w,y,x+w,y+h,col,6);
 for(let i=1;i<=5;i++){const xx=x+w*i/6,e=Math.sin(Math.PI*i/6),hh=(h-12)*e;s+=MW_ar(xx,y+h/2+hh/2,xx,y+h/2-hh/2,BLU,2.5)}
 return s+MW_T(x+w/2,y+h+24,'a',{fs:22,fw:800,a:'middle',fill:MW_G})+MW_T(x+w+10,y+h/2+8,'b',{fs:22,fw:800,fill:MW_G})};
/* the coupler: main guide (ports 1, 2) above the auxiliary guide (ports 4, 3), two holes in the shared wall */
const MW_coupler=(x,y,w,o={})=>{const gh=o.gh||34,gap=o.gap||22,h1=x+w*.42,h2=x+w*.58;
 return MW_guide(x,y,w,gh,BLU)+MW_guide(x,y+gh+gap,w,gh,ACC)+`<rect x="${h1-7}" y="${y+gh-2}" width="14" height="${gap+4}" fill="#FFFFFF"/><rect x="${h2-7}" y="${y+gh-2}" width="14" height="${gap+4}" fill="#FFFFFF"/>`
 +MW_badge(x-24,y+gh/2,'1',o.bc,o.bo)+MW_badge(x+w+24,y+gh/2,'2',o.bc,o.bo)+MW_badge(x-24,y+gh*1.5+gap,'4',o.bc,o.bo)+MW_badge(x+w+24,y+gh*1.5+gap,'3',o.bc,o.bo)};

